CREATE TABLE IF NOT EXISTS perfis(id INTEGER PRIMARY KEY AUTOINCREMENT, discord_id TEXT NOT NULL, nome TEXT NOT NULL, oab TEXT, npc INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS ix_perfis_d ON perfis(discord_id);
CREATE TABLE IF NOT EXISTS ministros(id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, discord_id TEXT, tipo TEXT NOT NULL DEFAULT 'npc', status TEXT NOT NULL DEFAULT 'ativo', presidente INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS processos(id INTEGER PRIMARY KEY AUTOINCREMENT, numero INTEGER NOT NULL UNIQUE, classe TEXT NOT NULL, assunto TEXT NOT NULL, sintese TEXT, pedido TEXT, liminar INTEGER NOT NULL DEFAULT 0, sigilo TEXT NOT NULL DEFAULT 'segredo', etiquetas TEXT NOT NULL DEFAULT '', situacao TEXT NOT NULL DEFAULT 'Em andamento', relator_id INTEGER REFERENCES ministros(id), perfil_id INTEGER REFERENCES perfis(id), autuado_em TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS partes(id INTEGER PRIMARY KEY AUTOINCREMENT, processo_id INTEGER NOT NULL REFERENCES processos(id) ON DELETE CASCADE, polo TEXT NOT NULL, nome TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_partes_p ON partes(processo_id);
CREATE TABLE IF NOT EXISTS andamentos(id INTEGER PRIMARY KEY AUTOINCREMENT, processo_id INTEGER NOT NULL REFERENCES processos(id) ON DELETE CASCADE, seq INTEGER NOT NULL, quando TEXT NOT NULL, titulo TEXT NOT NULL, descricao TEXT, responsavel TEXT NOT NULL, conteudo TEXT);
CREATE INDEX IF NOT EXISTS ix_and_p ON andamentos(processo_id, seq);
CREATE TABLE IF NOT EXISTS anexos(id INTEGER PRIMARY KEY AUTOINCREMENT, andamento_id INTEGER NOT NULL REFERENCES andamentos(id) ON DELETE CASCADE, titulo TEXT NOT NULL, url TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_anx_a ON anexos(andamento_id);
CREATE TABLE IF NOT EXISTS logs(id INTEGER PRIMARY KEY AUTOINCREMENT, quando TEXT NOT NULL, admin_id TEXT NOT NULL, acao TEXT NOT NULL, detalhes TEXT);
